<?php require __DIR__.'/../bootstrap.php';require_admin();$id=(int)getv('id');$s=db()->prepare('SELECT * FROM media_assets WHERE id=? AND kind=\'archive\'');$s->execute([$id]);$m=$s->fetch();if(!$m||!$m['storage_path'])exit('Archive not found.');$path=__DIR__.'/..'.$m['storage_path'];if(!class_exists('ZipArchive'))exit('ZIP inspection is unavailable because the PHP ZipArchive extension is disabled on this host.');$zip=new ZipArchive();if($zip->open($path)!==true)exit('Could not open ZIP.');$entries=[];for($i=0;$i<$zip->numFiles;$i++){ $st=$zip->statIndex($i);$name=$st['name'];$isDir=str_ends_with($name,'/');$entries[]=['index'=>$i,'name'=>$name,'size'=>(int)($st['size']??0),'dir'=>$isDir];}$title='Inspect ZIP';require __DIR__.'/../includes/header.php';?><div class="page-head"><div><span class="eyebrow">Archive</span><h1><?=e($m['name'])?></h1><p>Inspect archive contents without extracting them to disk. Media entries can be previewed through a streaming endpoint.</p></div><a class="btn secondary" href="/admin/media/">Back to Media</a></div><div class="card table-wrap"><table><tr><th>Path</th><th>Size</th><th>Actions</th></tr><?php foreach($entries as $x):?><tr><td><?=e($x['name'])?></td><td><?=number_format($x['size'])?> bytes</td><td><?php if(!$x['dir']):?><a class="btn small secondary" href="/admin/media-entry/?id=<?=$id?>&entry=<?=rawurlencode($x['name'])?>" target="_blank">Preview / Download</a><?php endif;?></td></tr><?php endforeach;?></table></div><form class="card" method="post" action="/admin/media-extract/"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><button class="btn">Extract Archive</button></form><?php $zip->close();require __DIR__.'/../includes/footer.php'; ?>